import { tv, type VariantProps } from "tailwind-variants";

const toggleGroup = tv({
  base: "flex items-center gap-1.5 rounded-xl data-[orientation='horizontal']:flex-row data-[orientation='vertical']:flex-col",
  variants: {
    outline: {
      false: "",
      true: "border border-border p-1.5 *:data-slot:border-none *:data-slot:shadow-none",
    },
  },
  defaultVariants: {
    outline: false,
  },
});

type ToggleGroupVariantProps = VariantProps<typeof toggleGroup>;

export { toggleGroup };
export type { ToggleGroupVariantProps };

"use client";

import { useDirection } from "@base-ui/react";
import { ToggleGroup as BaseToggleGroup } from "@base-ui/react/toggle-group";

import { mergeVariantClassName } from "@/registry/sector23/lib/merge-base-ui";

import {
  toggleGroup,
  type ToggleGroupVariantProps,
} from "./toggle-group.style";

function ToggleGroup({
  outline,
  className,
  ...props
}: BaseToggleGroup.Props & ToggleGroupVariantProps) {
  const direction = useDirection();

  return (
    <BaseToggleGroup
      data-slot="toggle-group"
      className={mergeVariantClassName(toggleGroup, { outline }, className)}
      {...props}
      dir={direction}
    />
  );
}

export { ToggleGroup };
